'use strict';
(function(){
const types=[{key:'icon',label:'ไอคอน',hint:'ใช้ในแถบสถานะ • ย่อด้านยาวไม่เกิน 128 px',side:128,limit:80000},{key:'portrait',label:'Portrait',hint:'ภาพประจำตัวในหน้าตัวละคร • ไม่ครอปภาพ',side:640,limit:240000},{key:'combat',label:'รูปตัวละครในฉากคอมแบท',hint:'เตรียมภาพเต็มตัว • รองรับพื้นหลังโปร่งใส • ไม่ครอปภาพ',side:1200,limit:480000}];
function image(src){return new Promise((resolve,reject)=>{const img=new Image(),timer=setTimeout(()=>{img.src='';reject(Error('โหลดภาพไม่สำเร็จ กรุณาตรวจไฟล์หรือลิงก์'));},15000);img.onload=()=>{clearTimeout(timer);resolve(img);};img.onerror=()=>{clearTimeout(timer);reject(Error('อ่านภาพไม่ได้ กรุณาใช้ PNG JPEG หรือ WebP'));};img.src=src;});}
async function fileSource(file,type){if(!/^image\/(png|jpeg|webp)$/.test(file.type))throw Error('รองรับไฟล์ PNG JPEG WebP');if(file.size>10*1024*1024)throw Error('ไฟล์ต้นฉบับต้องไม่เกิน 10 MB');const objectUrl=URL.createObjectURL(file);try{const img=await image(objectUrl),scale=Math.min(1,type.side/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const context=canvas.getContext('2d');context.drawImage(img,0,0,canvas.width,canvas.height);let src='';for(const quality of [.85,.7,.55,.4]){src=canvas.toDataURL('image/webp',quality);if(src.length<=type.limit)return src;}for(let i=0;i<3&&src.length>type.limit;i++){const small=document.createElement('canvas');small.width=Math.max(1,Math.round(canvas.width*.75));small.height=Math.max(1,Math.round(canvas.height*.75));small.getContext('2d').drawImage(canvas,0,0,small.width,small.height);canvas.width=small.width;canvas.height=small.height;canvas.getContext('2d').drawImage(small,0,0);src=canvas.toDataURL('image/webp',.65);}if(src.length>type.limit)throw Error('ภาพยังใหญ่เกินไป กรุณาลดขนาดไฟล์');return src;}finally{URL.revokeObjectURL(objectUrl);}}
function controller(host,prefix,statusNode,onBusy){let draft=R.validateCharacterImages(),state={};const message=t=>statusNode.textContent=t;const busy=()=>types.some(t=>state[t.key]?.busy);function updateBusy(){onBusy?.(busy());}
function paint(type){const entry=state[type.key],src=draft[type.key];entry.preview.hidden=!src;entry.placeholder.hidden=!!src;entry.preview.removeAttribute('src');if(src)entry.preview.src=src;entry.remove.disabled=!src&&!entry.busy;entry.note.textContent=entry.busy?'กำลังเตรียมภาพ…':src?'มีภาพแล้ว • บันทึกไปกับเซฟตัวละคร':'ยังไม่ได้ใส่รูป';}
async function change(type,producer){const entry=state[type.key],token=++entry.token;entry.busy=true;message('กำลังเตรียม '+type.label+'…');paint(type);updateBusy();try{const src=await producer();if(token!==entry.token)return;R.validateCharacterImages({...draft,[type.key]:src});draft[type.key]=src;entry.url.value=src.startsWith('http')?src:'';message('เตรียม '+type.label+' แล้ว • รูปจะบันทึกเมื่อยืนยันตัวละครหรือกดบันทึกรูป');}catch(e){if(token===entry.token)message(e.message);}finally{if(token===entry.token){entry.busy=false;entry.file.value='';paint(type);updateBusy();}}}
function reset(initial){for(const entry of Object.values(state))entry.token++;draft=R.validateCharacterImages(initial);host.replaceChildren();state={};message('');for(const type of types){const card=document.createElement('article');card.className='character-art-card';card.dataset.artType=type.key;const heading=document.createElement('h3');heading.textContent=type.label;const frame=document.createElement('div');frame.className='character-art-preview '+type.key;const preview=document.createElement('img');preview.alt=type.label+' ของตัวละคร';const placeholder=document.createElement('span');placeholder.textContent=type.key==='icon'?'👤':type.key==='portrait'?'Portrait':'Combat';frame.append(preview,placeholder);const label=document.createElement('label');label.textContent='อัปโหลดภาพ';const file=document.createElement('input');file.type='file';file.id=prefix+'-'+type.key+'-file';file.accept='image/png,image/jpeg,image/webp';label.htmlFor=file.id;label.append(file);const hint=document.createElement('small');hint.textContent=type.hint;const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='หรือใช้ลิงก์ภาพ';const url=document.createElement('input');url.type='url';url.id=prefix+'-'+type.key+'-url';url.placeholder='https://...';url.value=draft[type.key].startsWith('http')?draft[type.key]:'';const apply=document.createElement('button');apply.type='button';apply.textContent='ใช้ลิงก์ภาพ';apply.onclick=()=>change(type,async()=>{const src=url.value.trim();if(!src)throw Error('ใส่ลิงก์ภาพก่อน');R.validateCharacterImages({...draft,[type.key]:src});await image(src);return src;});details.append(summary,url,apply);const remove=document.createElement('button');remove.type='button';remove.textContent='ล้างรูป';remove.id=prefix+'-'+type.key+'-remove';const note=document.createElement('p');note.className='muted';state[type.key]={preview,placeholder,file,url,remove,note,busy:false,token:0};const entry=state[type.key];file.onchange=()=>{const selected=file.files[0];if(selected)change(type,()=>fileSource(selected,type));};remove.onclick=()=>{entry.token++;entry.busy=false;draft[type.key]='';url.value='';file.value='';paint(type);updateBusy();message('ล้าง '+type.label+' แล้ว • ยืนยันบันทึกเพื่อใช้การเปลี่ยนแปลง');};card.append(heading,frame,label,hint,details,remove,note);host.append(card);paint(type);}updateBusy();}
reset();return {reset,get(){if(busy())throw Error('รอให้เตรียมภาพเสร็จก่อนบันทึก');return R.validateCharacterImages(draft);},busy,cancel(){for(const entry of Object.values(state)){entry.token++;entry.busy=false;}updateBusy();}};}
const create=controller($('creationArtFields'),'createArt',$('creationArtStatus'),value=>{document.querySelector('#createForm button[type=submit]').disabled=value;});
const existing=controller($('existingArtFields'),'existingArt',$('existingArtStatus'),value=>{$('saveCharacterArt').disabled=value;});
function openExisting(){if(!s.character)return;existing.reset(s.character.images);$('characterArtDialog').showModal();}
$('characterArtForm').onsubmit=e=>{e.preventDefault();try{if(!s.character)throw Error('ยังไม่มีตัวละคร');s.character.images=existing.get();save();$('characterArtDialog').close();render();status('บันทึกรูปตัวละครแล้ว • ตรวจสถานะเซฟคลาวด์ก่อนเปลี่ยนเครื่อง');}catch(err){$('existingArtStatus').textContent=err.message;}};
$('cancelCharacterArt').onclick=()=>{existing.cancel();$('characterArtDialog').close();};$('characterArtDialog').addEventListener('cancel',()=>existing.cancel());
function renderCharacter(){const panel=$('characterPanel'),character=s.character;if(!character||!panel.firstElementChild)return;const images=R.validateCharacterImages(character.images),first=panel.firstElementChild,heading=first.querySelector('h2'),identity=document.createElement('div');identity.className='character-identity';if(images.icon){const icon=document.createElement('img');icon.src=images.icon;icon.alt='ไอคอน '+character.name;icon.className='character-icon';identity.append(icon);}if(heading){heading.before(identity);identity.append(heading);}if(images.portrait){const portrait=document.createElement('img');portrait.src=images.portrait;portrait.alt='Portrait '+character.name;portrait.className='character-portrait';first.append(portrait);}const edit=document.createElement('button');edit.type='button';edit.id='editCharacterArt';edit.textContent='แก้ไข / ดูรูปตัวละคร';edit.onclick=openExisting;first.append(edit);}
window.EverTaleCharacterArt={resetCreation:images=>create.reset(images),creationImages:()=>create.get(),renderCharacter,reset(){create.reset();existing.reset();if($('characterArtDialog').open)$('characterArtDialog').close();}};
})();
